const D = { scale:1, energy:.6, hue:150, speed:1, density:.5, dome:1, hull:1, beam:1, style:'pulp', pose:'hover', act:'abduct', seed:0, x:.5, y:.4 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const v = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return v - Math.floor(v); };
const u = Math.min(width,height), TAU=Math.PI*2, PI=Math.PI;
const H = ((P.hue%360)+360)%360;
const en=P.energy, spd=P.speed;
let bt=K.beat*spd;
if (S.lb==null || bt<S.lb) S.lb=bt; S.lb=bt;
const puls=Math.max(0,K.pulse||0), swell=Math.max(0,K.swell||0);
const sect=K.section||0, inten=(K.intensity!=null?K.intensity:.6);
const rms=Math.min(1,(A.rms||0)*2.4), bassv=Math.min(1,A.bass||0), air=Math.min(1,A.treble||0);
const gt=K.t||0;
const st=P.style;
const seedShift=(fr(1)-0.5);

// ---- act / dramaturgy (multi-minute) ----
let beamOn, beamSweep, domeDrive, driftScale, tiltBias;
if (P.act==='scan'){ beamOn=0.9; beamSweep=1; domeDrive=0.7+inten*0.4; driftScale=0.9; tiltBias=0; }
else if (P.act==='cruise'){ beamOn=0.0; beamSweep=0; domeDrive=0.55+inten*0.5; driftScale=1.25; tiltBias=0.35; }
else { beamOn=1; beamSweep=0.28; domeDrive=1+inten*0.3; driftScale=0.55; tiltBias=0; } // abduct
// section can escalate abduction over minutes
const escal = 0.6 + inten*0.6;

// ---- pose (immediate attitude) ----
const pose=P.pose;
let bobK=1, bankK=1, spin=0, wobK=1;
if (pose==='bob'){ bobK=2.2; bankK=0.6; }
else if (pose==='bank'){ bobK=0.7; bankK=2.4; }
else if (pose==='spin'){ bobK=1.1; bankK=1.4; spin=1; wobK=1.6; }
else if (pose==='park'){ bobK=0.35; bankK=0.3; wobK=0.4; }
// 'hover' = defaults

const eM=(0.45+en);
const R=u*0.24*P.scale*(0.85+P.hull*0.15);
const discH=R*0.34*(0.8+P.hull*0.3);
const ax=P.x*width, ay=P.y*height;

// hover motion — displaces whole silhouette
const bob=( swell*0.55 + Math.sin(gt*0.9+seedShift)*0.55 + puls*0.35 + bassv*0.4 )*R*0.17*eM*bobK;
const sway=( Math.sin(gt*0.6+seedShift*2)*0.7 + Math.sin(gt*0.31)*0.3 )*R*0.42*eM*driftScale*wobK;
const bank=( Math.sin(gt*0.5)*0.11*eM*bankK + Math.sin(bt*PI)*0.028*eM + tiltBias*Math.sin(gt*0.2)*0.14 );
const cx=ax+sway, cy=ay+bob;
const bottomY=cy+discH*0.62;

// ============ BEAM (behind hull) ============
const floorY=height*1.03;
const bx=cx + Math.sin(gt*0.85)*beamSweep*R*0.55 + (P.act==='scan'?Math.sin(gt*0.4)*R*0.25:0);
const topW=R*0.40, botW=R*1.28*P.beam;
if (beamOn>0.02){
  const bh=(st==='thermal')?28:(st==='noir'?H:(H+22)%360);
  const bsat=(st==='noir')?14:58;
  push(); blendMode(ADD); noStroke();
  for (let s=0;s<3;s++){
    const a=beamOn*(8-s*2)*(0.7+domeDrive*0.4)*(0.85+rms*0.5);
    const tw=topW*(1+s*0.18), bw=botW*(1+s*0.34);
    fill(bh, bsat, 100, a);
    beginShape();
    vertex(cx-tw, bottomY); vertex(cx+tw, bottomY);
    vertex(bx+bw, floorY); vertex(bx-bw, floorY);
    endShape(CLOSE);
  }
  // horizontal scan bands to make beam read as energy
  for (let i=0;i<5;i++){
    const ph=((gt*(0.5+beamSweep*0.6)+i/5)%1);
    const yy=floorY-ph*(floorY-bottomY);
    const axisX=bx+(cx-bx)*ph, wdt=botW+(topW-botW)*ph;
    fill(bh, bsat*0.6, 100, beamOn*10*(1-ph));
    ellipse(axisX, yy, wdt*2, discH*0.28);
  }
  blendMode(BLEND); pop();
}

// ============ TRACTOR SPARKLES + ABDUCTEE ============
if (beamOn>0.02){
  const N=Math.round(12+P.density*30);
  push(); blendMode(ADD); noStroke();
  for (let i=0;i<N;i++){
    const spd2=0.28*(0.55+fr(i)*1.0)*(0.7+beamOn*0.6);
    const ph=(gt*spd2 + fr(i+9))%1; // 0 bottom -> 1 top (rising)
    const yy=floorY-ph*(floorY-bottomY);
    const axisX=bx+(cx-bx)*ph, wdt=(botW+(topW-botW)*ph);
    const off=(fr(i+3)-0.5)*wdt*1.5 + Math.sin(gt*2.2+i)*R*0.05;
    const br=(1-ph)*(0.6+air*0.6);
    const sz=(1.4+fr(i+5)*3)*(R/60)*(0.6+br);
    fill((st==='thermal')?40:(H+40)%360, 30, 100, 65*br);
    ellipse(axisX+off, yy, sz, sz);
  }
  blendMode(BLEND); pop();
  // abductee — a small silhouette spinning as it rises (abduct act only)
  if (P.act==='abduct'){
    const ph=(gt*0.11)%1, yy=floorY-ph*(floorY-(bottomY+discH));
    const axisX=bx+(cx-bx)*ph, sc=(0.45+ph*0.6)*R*0.17;
    push(); translate(axisX,yy); rotate(Math.sin(gt*1.3)*0.5+gt*0.3);
    fill(0,0,st==='noir'?4:8, 78); noStroke();
    // cow-ish silhouette
    ellipse(0,0,sc*2.1,sc*1.15); ellipse(-sc*0.9,-sc*0.2,sc*0.9,sc*0.8);
    rect(-sc*0.8,sc*0.3,sc*0.28,sc*0.7,2); rect(sc*0.55,sc*0.3,sc*0.28,sc*0.7,2);
    pop();
  }
}

// ============ SAUCER HULL ============
push(); translate(cx,cy); rotate(bank);
noStroke();
const blueprint=(st==='blueprint'), noir=(st==='noir'), chrome=(st==='chrome'), thermal=(st==='thermal'), pulp=(st==='pulp');

if (blueprint){
  // schematic wireframe — cyan lines, no fill
  const cH=(H+120)%360;
  stroke(cH,60,100,90); strokeWeight(Math.max(1,R*0.012)); noFill();
  ellipse(0,0,R*2,discH*2);                       // hull equator
  ellipse(0,-discH*0.2,R*1.15,discH*1.1);         // upper hull
  ellipse(0,discH*0.35,R*1.4,discH*1.0);          // lower hull
  arc(0,-discH*0.1,R*P.dome,R*P.dome*1.1,PI,TAU);  // dome
  // section lines
  for(let i=-3;i<=3;i++){ const xx=i/3*R*0.92; const hh=discH*Math.sqrt(Math.max(0,1-(xx/R)*(xx/R))); line(xx,-hh,xx,hh); }
  // tick marks + crosshair
  stroke(cH,60,100,55); strokeWeight(1);
  for(let i=0;i<24;i++){ const an=i/24*TAU; const c=Math.cos(an),s2=Math.sin(an); line(c*R,s2*discH,c*R*1.08,s2*discH*1.08); }
  stroke(cH,40,100,40); line(-R*1.25,0,R*1.25,0); line(0,-R*0.8,0,discH*1.6);
  noStroke();
} else {
  // ---- solid hull (pulp / chrome / thermal / noir) ----
  // lower belly
  let belly, mid, top, rimC;
  if (noir){ belly=[H,20,10]; mid=[H,16,20]; top=[H,10,34]; rimC=[H,8,96]; }
  else if (chrome){ belly=[H,14,32]; mid=[H,8,66]; top=[H,6,96]; rimC=[(H+30)%360,30,100]; }
  else if (thermal){ belly=[250,80,60]; mid=[10,85,95]; top=[45,90,100]; rimC=[55,95,100]; }
  else { belly=[(H+8)%360,55,40]; mid=[H,42,66]; top=[H,30,90]; rimC=[(H+30)%360,85,100]; } // pulp teal-ish

  // pulp misregistration ghost
  if (pulp){ fill((H+330)%360,70,90,45); ellipse(R*0.05,discH*0.12+2,R*2,discH*1.7); }
  // belly (lower dome)
  fill(belly[0],belly[1],belly[2]); ellipse(0,discH*0.32,R*1.5,discH*1.9);
  // main hull disc with vertical shading bands
  const bands=chrome?9:(thermal?7:5);
  for(let i=0;i<bands;i++){
    const f=i/(bands-1);
    let cc;
    if (thermal){ const hh=[250,210,10,45,55][Math.min(4,Math.floor(f*4.999))]; cc=[hh,85,60+f*40]; }
    else { cc=[mid[0], mid[1]*(1-f*0.5), mid[2]+(top[2]-mid[2])*(1-f)]; }
    fill(cc[0],cc[1],cc[2]);
    const yy=-discH + f*discH*2, hh=discH*2/bands+1;
    // clip band to hull ellipse via width from ellipse eq
    const rel=(yy)/discH; const wf=Math.sqrt(Math.max(0,1-rel*rel*0.6));
    ellipse(0,yy+hh*0.5, R*2*wf, hh*1.6);
  }
  // rim band (equator) — bright accent stripe
  fill(rimC[0],rimC[1],rimC[2], noir?60:100);
  ellipse(0,0,R*2,discH*0.6);
  fill((H+8)%360, chrome?6:40, noir?12:24, 70);
  ellipse(0,discH*0.02,R*2,discH*0.34);

  // pulp halftone dots over hull (hue-independent ink)
  if (pulp){
    push(); drawingContext.save();
    drawingContext.beginPath();
    drawingContext.ellipse(0,0,R,discH,0,0,TAU); drawingContext.clip();
    blendMode(MULTIPLY); noStroke(); fill(0,0,0,32);
    const cols=13, rows=6;
    for(let cxi=0;cxi<cols;cxi++) for(let ry=0;ry<rows;ry++){
      const xx=(cxi/(cols-1)-0.5)*R*2, yy=(ry/(rows-1)-0.5)*discH*2;
      const d=1-(yy+discH)/(discH*2); const ds=(0.6+d*1.6)*(R/34);
      ellipse(xx,yy,ds,ds);
    }
    drawingContext.restore(); blendMode(BLEND); pop();
  }
  // outline
  if (!chrome){ noFill(); stroke(0,0, noir?70:8, noir?55:80); strokeWeight(Math.max(1.2,R*0.02)); ellipse(0,0,R*2,discH*2); noStroke(); }
}

// ---- rim lights / portholes (chase) — all styles ----
const nL=Math.round(9+P.density*10);
push(); if(!blueprint&&!noir) blendMode(ADD);
for(let i=0;i<nL;i++){
  const an=i/nL*TAU + (spin?gt*1.4:0) + gt*0.05;
  const lx=Math.cos(an)*R*0.92, ly=Math.sin(an)*discH*0.9;
  if (ly<-discH*0.15) continue; // hide top-back lights behind dome-ish
  const chase=Math.pow(Math.max(0,Math.sin(an - bt*PI*1.0 + gt*0.3)),4);
  const on=0.25+chase*0.75;
  const br=(50+on*50)*(0.7+puls*0.4+air*0.4);
  const lh=(thermal)?(40- i*3):((H+ i*20 + (chrome?0:60))%360);
  fill(lh, blueprint?50:(chrome?40:90), Math.min(100,br), blueprint?70:100);
  const ls=R*0.11*(0.7+chase*0.6);
  drawingContext.shadowBlur = (on>0.6&&!blueprint)? R*0.18:0; drawingContext.shadowColor='rgba(255,255,255,0.5)';
  ellipse(lx,ly,ls,ls);
}
drawingContext.shadowBlur=0; blendMode(BLEND); pop();

// ---- DOME (glassy, glows with rms) ----
const domeR=R*0.5*P.dome, domeH=domeR*1.05;
const dGlow=Math.min(100, 42 + rms*45*domeDrive + puls*22 + swell*10);
if (blueprint){
  noFill(); stroke((H+120)%360,60,100,90); strokeWeight(Math.max(1,R*0.012));
  arc(0,-discH*0.1,domeR*2,domeH*2,PI,TAU);
} else {
  // dome body
  push(); if(!noir) drawingContext.shadowBlur=domeR*0.4, drawingContext.shadowColor='rgba(180,255,220,0.6)';
  fill((thermal)?50:(H+40)%360, chrome?24:(noir?40:70), dGlow, 92);
  arc(0,-discH*0.1,domeR*2,domeH*2,PI,TAU,CHORD);
  drawingContext.shadowBlur=0;
  // inner core light
  fill((thermal)?55:(H+50)%360, 20, Math.min(100,dGlow+25), 90);
  ellipse(-domeR*0.12,-discH*0.1-domeH*0.35, domeR*0.9, domeH*0.7);
  // rim highlight
  noFill(); stroke(0,0,100,noir?40:70); strokeWeight(Math.max(1,R*0.014));
  arc(0,-discH*0.1,domeR*2,domeH*2,PI+0.15,TAU-0.15);
  noStroke(); pop();
  // little alien silhouette in dome (peeks) — non-noir
  if (!blueprint){
    fill(0,0, noir?6:10, 55);
    ellipse(domeR*0.18,-discH*0.1-domeH*0.28, domeR*0.34, domeR*0.42);
  }
}
pop(); // hull transform

// ---- ambient glow halo under saucer on the bed ----
if (!blueprint){
  push(); blendMode(ADD); noStroke();
  fill((H+30)%360, 40, 100, 6+rms*10+puls*6);
  ellipse(cx, cy, R*3.0, discH*3.2);
  blendMode(BLEND); pop();
}
